WITH src AS (SELECT * FROM store_sales WHERE units <= 14), units_bucket_summary AS (SELECT CASE WHEN units >= 41 THEN 'high' WHEN units >= 13 THEN 'mid' ELSE 'low' END AS units_bucket, DATE_TRUNC('MONTH', sale_date) AS sale_month, COUNT(DISTINCT revenue) AS unique_stores FROM src GROUP BY CASE WHEN units >= 41 THEN 'high' WHEN units >= 13 THEN 'mid' ELSE 'low' END, DATE_TRUNC('MONTH', sale_date)) SELECT * FROM units_bucket_summary WHERE unique_stores >= 7 ORDER BY unique_stores DESC, units_bucket, sale_month LIMIT 3;
